<script setup>
import { nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import AppIcon from '../../components/AppIcon.vue'
import { adminApi } from '../../api/services.js'
import { useSeo } from '../../composables/useSeo.js'
import { formatDateTime, formatMoney, orderSourceLabel, orderStatusLabel } from '../../utils/format.js'

const days=ref(30),data=ref(null),loading=ref(true),error=ref(''),salesCanvas=ref(null),statusCanvas=ref(null)
let salesChart,statusChart
useSeo({title:'Overview | Velmora Admin',description:'Analytics dashboard.',path:'/admin',noindex:true})
async function draw(){if(!data.value)return;await nextTick();const Chart=(await import('chart.js/auto')).default;salesChart?.destroy();statusChart?.destroy();salesChart=new Chart(salesCanvas.value,{type:'line',data:{labels:data.value.sales.map(x=>x.date),datasets:[{label:'Revenue',data:data.value.sales.map(x=>x.revenue_minor/100),tension:.3,fill:true},{label:'Order',data:data.value.sales.map(x=>x.orders),tension:.3,yAxisID:'y1'}]},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{labels:{color:'#B7BAAE'}}},scales:{x:{ticks:{color:'#777B72',maxRotation:0},grid:{color:'rgba(68,76,56,.2)'}},y:{ticks:{color:'#777B72'},grid:{color:'rgba(68,76,56,.2)'}},y1:{position:'right',ticks:{color:'#777B72',precision:0},grid:{drawOnChartArea:false}}}}});statusChart=new Chart(statusCanvas.value,{type:'doughnut',data:{labels:data.value.statuses.map(x=>orderStatusLabel(x.status)),datasets:[{data:data.value.statuses.map(x=>x.count),borderWidth:0}]},options:{responsive:true,maintainAspectRatio:false,cutout:'72%',plugins:{legend:{position:'bottom',labels:{color:'#B7BAAE',boxWidth:10}}}}})}
async function load(){loading.value=true;error.value='';try{data.value=await adminApi.dashboard(days.value);await draw()}catch{error.value='Could not load analytics.'}finally{loading.value=false}}
onMounted(load);watch(days,load);onBeforeUnmount(()=>{salesChart?.destroy();statusChart?.destroy()})
</script>
<template><section class="admin-page"><div class="admin-page-head"><div><p>ANALYTICS</p><h1 class="ui-display">Store overview</h1><span>Sales, customers and orders that need attention.</span></div><select v-model.number="days" class="admin-select"><option :value="7">7 days</option><option :value="30">30 days</option><option :value="90">90 days</option><option :value="365">365 days</option></select></div><div v-if="error" class="admin-alert">{{error}}</div><div v-if="loading&&!data" class="admin-loading">Loading…</div><template v-if="data">
<div class="admin-stats"><article><span class="admin-stat-icon"><AppIcon name="cart"/></span><small>Orders today</small><strong>{{data.summary.orders_today}}</strong><em>{{data.summary.total_orders}} in period</em></article><article><span class="admin-stat-icon"><AppIcon name="pulse"/></span><small>Revenue today</small><strong>{{formatMoney(data.summary.revenue_today_minor)}}</strong><em>{{formatMoney(data.summary.paid_revenue_minor)}} in period</em></article><article><span class="admin-stat-icon"><AppIcon name="connection"/></span><small>Average order</small><strong>{{formatMoney(data.summary.average_order_minor)}}</strong><em>paid orders</em></article><article><span class="admin-stat-icon"><AppIcon name="phone"/></span><small>Customers</small><strong>{{data.summary.unique_customers}}</strong><em>{{data.summary.active_products}} active products</em></article></div>
<div class="admin-attention-grid"><RouterLink :to="{path:'/admin/orders',query:{status:'new'}}"><strong>{{data.summary.new_orders}}</strong><span>new orders</span></RouterLink><RouterLink :to="{path:'/admin/orders',query:{status:'processing'}}"><strong>{{data.summary.processing_orders}}</strong><span>processing</span></RouterLink><RouterLink :to="{path:'/admin/orders',query:{payment_status:'unpaid'}}"><strong>{{data.summary.unpaid_orders}}</strong><span>awaiting payment</span></RouterLink><RouterLink :to="{path:'/admin/orders',query:{status:'shipped'}}"><strong>{{data.summary.shipped_without_tracking}}</strong><span>shipped without tracking</span></RouterLink></div>
<div class="admin-chart-grid"><article class="admin-panel admin-chart-panel"><div class="admin-panel-head"><div><small>TRENDS</small><h2>Sales & revenue</h2></div></div><div class="admin-chart"><canvas ref="salesCanvas"></canvas></div></article><article class="admin-panel admin-chart-panel admin-chart-panel--compact"><div class="admin-panel-head"><div><small>STATUSES</small><h2>Order</h2></div></div><div class="admin-chart admin-chart--donut"><canvas ref="statusCanvas"></canvas></div></article></div>
<div class="admin-dashboard-grid"><article class="admin-panel"><div class="admin-panel-head"><div><small>RECENT</small><h2>New orders</h2></div><RouterLink to="/admin/orders">All orders</RouterLink></div><div class="admin-dashboard-list"><RouterLink v-for="o in data.recent_orders" :key="o.id" :to="`/admin/orders/${o.id}`"><span><strong>#{{o.order_number}}</strong><small>{{o.customer_name}} · {{formatDateTime(o.created_at)}}</small></span><span><strong>{{formatMoney(o.total_minor,o.currency)}}</strong><small>{{orderStatusLabel(o.status)}}</small></span></RouterLink></div></article><article class="admin-panel"><div class="admin-panel-head"><div><small>SOURCES</small><h2>Order sources</h2></div></div><div class="admin-source-list"><div v-for="s in data.sources" :key="s.source"><span>{{orderSourceLabel(s.source)}}</span><strong>{{s.count}}</strong></div></div></article></div>
<div class="admin-panel"><div class="admin-panel-head"><div><small>SALES</small><h2>Top products</h2></div></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Product</th><th>Quantity</th><th>Revenue</th></tr></thead><tbody><tr v-for="x in data.top_products" :key="x.product_slug"><td><strong>{{x.title}}</strong><small>{{x.product_slug}}</small></td><td>{{x.quantity}}</td><td>{{formatMoney(x.revenue_minor)}}</td></tr><tr v-if="!data.top_products.length"><td colspan="3" class="admin-empty-cell">No data yet.</td></tr></tbody></table></div></div>
</template></section></template>
